after.scss:
@use "gerillass" as *;

.bell {
  @include after {
    position: absolute;
    top: 6px;
    right: 6px;
    width: 8px;
    height: 8px;
    border-radius: 50%;
    background: #ed6a5a;
  }
}

all-buttons.scss:
@use "gerillass" as *;

@include all-buttons {
  padding: 11px 20px;
  border: 0;
  border-radius: 10px;
  background-color: #668f80;
  color: #fff;
  font: 600 14px Inter, ui-sans-serif, system-ui, sans-serif;
}

@include all-buttons(hover) {
  background-color: #2f3937;
}

@include all-buttons(focus) {
  background-color: #2f3937;
}

@include all-buttons(active) {
  background-color: #2f3937;
}

@include all-buttons(disabled) {
  background-color: #f2f2eb;
  color: #657167;
}

all-text-inputs.scss:
@use "gerillass" as *;

@include all-text-inputs {
  width: 100%;
  height: 38px;
  padding: 0 12px;
  border: 1px solid #dee0cd;
  border-radius: 6px;
  background: #fff;
  font: inherit;
  color: inherit;
}

select {
  width: 100%;
  height: 38px;
  padding: 0 8px;
  border: 1px solid #dee0cd;
  border-radius: 6px;
  background: #fff;
  font: inherit;
}

aspect-ratio.scss:
@use "gerillass" as *;

.video iframe {
  @include aspect-ratio("16/9");
}

.avatar {
  @include aspect-ratio("1:1", contain);
}

.panel {
  @include aspect-ratio(1.5, null);
}

background-image.scss:
@use "gerillass" as *;

.marks {
  @include background-image("/images/general/sass-logo-black.svg", $size: 56px, $position: left top, $repeat: repeat);
}

.marks-washed {
  @include background-image("/images/general/sass-logo-black.svg", rgb(102 143 128 / 0.75), $size: 56px, $position: left top, $repeat: repeat);
}

before.scss:
@use "gerillass" as *;

.steps {
  counter-reset: step;
}

.step {
  counter-increment: step;
  @include before(counter(step)) {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 24px;
    height: 24px;
    margin-right: 10px;
    border-radius: 50%;
    background: #222c25;
    color: #fafaf8;
    font-size: 12px;
    font-weight: 600;
  }
}

breakpoint.scss:
@use "gerillass" as *;

.header{
  @include breakpoint(min, large) {
    padding: 2rem 4rem;
  };
}

.card{
  @include breakpoint(between, small large) {
    flex: 0 0 50%;
  };
}

.sidebar{
  @include breakpoint(max, medium) {
    display: none;
  };
}

.footer{
  @include breakpoint(only, 1200px) {
    text-align: center;
  };
}

breakpointer.scss:
@use "gerillass" as *;

@include breakpointer {
  position: fixed;
  top: 0;
  right: 0;
  color: white;
  padding: 5px 10px;
  z-index: 10;
}

center.scss:
@use "gerillass" as *;

.parent-element {
  position: relative;
  .element{
    position: absolute;
    @include center(horizontal);
  }
}

columnizer.scss:
@use "gerillass" as *;

.parent-element{
  @include columnizer(2, 10px, true);
  @include breakpoint(min, large) {
    @include columnizer(4, 20px, false);
  }
}

container-query.scss:
@use "gerillass" as *;

.card {
  @include container("card");
}

// The query goes on a descendant of the container, never on the
// container itself. Nothing warns you when it is on the wrong element.
.card .title {
  @include container-query("min", 400px) {
    font-size: 2rem;
  }
}

counter.scss:
@use "gerillass" as *;

.ingredients {
  @include counter("(", lower-alpha, ")", $name: ingredients) {
    margin-right: 6px;
    color: #69995d;
  }
}

.ingredients-more {
  @include counter("(", lower-alpha, ")", $continue: ingredients) {
    margin-right: 6px;
    color: #69995d;
  }
}

.method {
  @include counter(decimal, ".", $name: method) {
    margin-right: 6px;
    font-weight: 700;
  }
}

.method-more {
  @include counter(decimal, ".", $continue: method) {
    margin-right: 6px;
    font-weight: 700;
  }
}

escape-to-parent.scss:
@use "gerillass" as *;

.panel {
  @include escape-to-parent(".theme-dark") {
    background: #222c25;
    border-color: #2f3937;
  }

  .price {
    color: #668f80;

    @include escape-to-parent(".theme-dark") {
      color: #fafaf8;
    }
  }
}

font-face.scss:
@use "gerillass" as *;

@include font-face("Roboto", "/fonts/roboto/roboto-v20-latin-ext_latin-regular");
@include font-face("Roboto", "/fonts/roboto/roboto-v20-latin-ext_latin-italic", italic);
@include font-face("Roboto", "/fonts/roboto/roboto-v20-latin-ext_latin-700", 700);
@include font-face("Roboto", "/fonts/roboto/roboto-v20-latin-ext_latin-700italic", italic, 700);

gradient.scss:
@use "gerillass" as *;

.ring{
  display: grid;
  place-items: center;
  width: 160px;
  height: 160px;
  border-radius: 50%;
  @include gradient((#5bc0bb 0 72%) (#f2f2eb 72% 100%), conic);

  &::before{
    content: "72%";
    display: grid;
    place-items: center;
    width: 124px;
    height: 124px;
    border-radius: 50%;
    background: #fff;
    font: 600 28px/1 system-ui, sans-serif;
    color: #668f80;
  }
}

hide.scss:
@use "gerillass" as *;

.skip-link {
  position: absolute;
  top: 12px;
  left: 12px;
  padding: 10px 16px;
  border-radius: 6px;
  background: #222c25;
  color: #fafaf8;
  @include hide(focusable);
}

loadify.scss:
@use "gerillass" as *;

@include loadify(init);

.parent-element {
  .item {
    @include only(1) {
      @include loadify(0.2s, 0.6s);
    }
    @include only(2) {
      @include loadify(0.4s, 0.6s);
    }
    @include only(3) {
      @include loadify(0.6s, 0.6s);
    }
  }
}

long-shadow.scss:
@use "gerillass" as *;

$ink: oklch(0.21 0.04 265);

.button {
  @include long-shadow($ink, 10px, bottom-right, $step: 2px);

  &:hover {
    @include long-shadow($ink, 16px, bottom-right, $step: 2px);
    translate: -4px -4px;
  }

  &:active {
    @include long-shadow($ink, 4px, bottom-right, $step: 2px);
    translate: 4px 4px;
  }
}

motion-safe.scss:
@use "gerillass" as *;

@keyframes fade-in {
  from { opacity: 0; transform: translateY(6px); }
}

@include motion-safe {
  .badge {
    animation: fade-in 0.6s ease both;
  }
}

only.scss:
@use "gerillass" as *;

.cards {
  .card {
    @include only(2) {
      background-color: #5bc0bb;
    }
  }
}

.articles {
  article {
    @include only(-1) {
      border-bottom: 0;
    }
  }
}

.gallery {
  figure {
    @include only(1, -1) {
      grid-column: span 2;
    }
  }
}

placeholder-shown.scss:
@use "gerillass" as *;

input {
  @include placeholder-shown {
    border-style: dashed;
    background-color: #fafaf8;
  }
}

reveal.scss:
@use "gerillass" as *;

.menu {
  display: none;

  @include reveal(".is-open", 200ms, right 1rem, null, false);
}

.menu.is-open {
  display: block;
}

scissors.scss:
@use "gerillass" as *;

.element{
  height: 200px;
  display: flex;
  justify-content: center;
  background-color: #668f80;
  @include scissors(0 0 50% 50%);
  h2 {
    color: white;
    font-size: 2.5em; 
    text-align: center;
  }
}

sprite.scss:
@use "gerillass" as *;

.frame {
  width: 100px;
  height: 100px;
  @include sprite("/images/docs/sprite.png");
}

.frame--1 { @include sprite(0 0); }
.frame--2 { @include sprite(-100px 0); }
.frame--3 { @include sprite(-200px 0); }
.frame--4 { @include sprite(-300px 0); }

text-gradient.scss:
@use "gerillass" as *;

.premium{
  font: 900 48px/1 system-ui, sans-serif;
  @include text-gradient(
    (#2f3937 0%) (#69995d 45%) (#f2f2eb 50%) (#bdc488 55%) (#2f3937 100%),
    $direction: top
  );
}

text-shadow.scss:
@use "gerillass" as *;

.sign {
  @include text-shadow(
    top #5bc0bb 0px 4px,
    top #5bc0bb 0px 10px,
    top #2f3937 0px 20px
  );

  @include motion-safe {
    transition: text-shadow 0.35s ease;
  }

  &:hover {
    @include text-shadow(
      top #5bc0bb 0px 10px,
      top #5bc0bb 0px 26px,
      top #2f3937 0px 52px
    );
  }
}

text-stroke.scss:
@use "gerillass" as *;

.menu a {
  @include text-stroke(2px, #222c25, hollow);

  @include motion-safe {
    transition: -webkit-text-fill-color 0.25s ease;
  }

  &:hover,
  &:focus-visible {
    @include text-stroke(2px, #222c25, hollow, #222c25);
    -webkit-text-fill-color: #69995d;
  }
}

tokens.scss:
@use "gerillass" as *;

:root {
  @include tokens((1: 0.25rem, 2: 0.5rem, 3: 0.75rem, 4: 1rem), space);
  @include tokens((md: 8px, lg: 12px, full: 9999px), radius);
  @include tokens((sans: ("Inter", system-ui, sans-serif)), font);
  @include tokens((sm: 0.875rem, lg: 1.125rem), text);
  @include tokens((md: 0 4px 12px rgb(34 44 37 / 0.08)), shadow);
}

.card {
  display: grid;
  gap: var(--space-2);
  padding: var(--space-4);
  border-radius: var(--radius-lg);
  font-family: var(--font-sans);
  font-size: var(--text-sm);
  box-shadow: var(--shadow-md);
}

.card .title {
  font-size: var(--text-lg);
}

.card .pill {
  justify-self: start;
  padding: var(--space-1) var(--space-3);
  border-radius: var(--radius-full);
}

triangle.scss:
@use "gerillass" as *;

.element{
  &::after {
    @include triangle(
      $direction: "bottom",
      $color: #db504a,
      $size: 10px 6px
    ) {
      position: relative;
      margin-left: 6px;
      top: -2px;
    };
  }
}
